Here is the root cause:
The `asix_read_phy_addr()` function in `asix_common.c` did not validate the PHY address returned by the USB device, allowing an invalid address (>= PHY_MAX_ADDR) to propagate. This caused a warning in `mdiobus_get_phy()`. Validation was only performed in one caller (`ax88172a_bind`), leaving other callers vulnerable.

Here is the patch:

 int asix_read_phy_addr(struct usbnet *dev, bool internal)
 {
 	int ret, offset;
 	u8 buf[2];

 	ret = asix_read_cmd(dev, AX_CMD_READ_PHY_ID, 0, 0, 2, buf, 0);
 	if (ret < 0)
 		goto error;

 	if (ret < 2) {
 		ret = -EIO;
 		goto error;
 	}

 	offset = (internal ? 1 : 0);
 	ret = buf[offset];

+	if (ret >= PHY_MAX_ADDR) {
+		netdev_err(dev->net, "invalid PHY address: %d\n", ret);
+		return -ENODEV;
+	}
+
 	netdev_dbg(dev->net, "%s PHY address 0x%x\n",
 		   internal ? "internal" : "external", ret);

 	return ret;

 error:
 	netdev_err(dev->net, "Error reading PHY_ID register: %02x\n", ret);

 	return ret;
 }



